mapper.select:
SELECT s.SCHEDULE_NO AS scheduleNo , s.START_TIME AS startTime , s.END_TIME AS endTime , r.CUSTOMER_NAME AS customerName , r.SYMPTOM AS symptom FROM AS_SCHEDULE s
JOIN AS_REQUEST r ON s.REQUEST_NO = r.REQUEST_NO
JOIN ENGINEER e ON s.ENGINEER_NO = e.ENGINEER_NO WHERE e.MEM_NO = #{memNo} AND DATE(s.START_TIME) = CURDATE() ORDER BY s.START_TIME;

SELECT DISTINCT DATE(s.START_TIME) AS scheduleDate
FROM AS_SCHEDULE s
JOIN ENGINEER e ON s.ENGINEER_NO = e.ENGINEER_NO
WHERE e.MEM_NO = #{memNo}
AND YEAR(s.START_TIME) = #{year}
AND MONTH(s.START_TIME) = #{month};

mapper.insert:
INSERT INTO AS_RESULT (
SCHEDULE_NO
, PROCESS_DATE
, PROCESS_CONTENT
, RESULT_STATUS
, IMAGE_PATH
)
VALUES (
#{scheduleNo}
, #{processDate}
, #{processContent}
, #{resultStatus}
, #{imagePath});
